#!/usr/bin/env node
// Emit a marker-bounded "Page history" footer on every wiki page, rendered
// from `git log --follow` for that file. Brand-legal and regulatory-affairs
// readers can read the version history in-page without git access.
//
// Today's contract:
//   - Up to 5 most-recent commits per page
//   - Each entry: short sha (linkable to GitHub), ISO date, commit subject
//   - Marker-bounded so the block is idempotent (re-runs replace, not append)
//   - Auto-generated pages (`auto_generated: true`) get a simplified history
//     pointing at their generator rather than per-page git log
//
// Mature state: each entry will be a clickable DataCite DOI version when the
// per-page DOI minting integration lands. The field path is already reserved
// as `wiki_doi:` in frontmatter (see tools/migrate-future-slots.mjs).
//
// Runs in prebuild after sync-source-counts so the changelog block reflects
// the most recent count-sync commits.

import fs from "node:fs"
import path from "node:path"
import { execSync } from "node:child_process"

const repoRoot = process.cwd()
const beginMarker = "<!-- BEGIN: hmi-page-history -->"
const endMarker = "<!-- END: hmi-page-history -->"
const GITHUB_BASE = "https://github.com/paleofoundation/heavymetalindex/commit"
const MAX_ENTRIES = 5

const TARGETS = [
  "wiki/sources",
  "wiki/ingredients",
  "wiki/products",
  "wiki/metals",
  "wiki/regulations",
  "wiki/synthesis",
]

const args = process.argv.slice(2)
const dryRun = args.includes("--dry-run")
const verbose = args.includes("--verbose")

// Single git pass: read the full log of all wiki pages with --name-only so we
// can attribute commits to files in one shot. ~1ms per commit on a warm repo
// vs ~25ms per file for individual `git log` calls — for 1800 files that's
// the difference between 45 seconds and ~1 second.
let logRaw = ""
try {
  logRaw = execSync(
    `git log --name-only --pretty=format:"COMMIT|%h|%ai|%s" -- ${TARGETS.map((t) => `'${t}'`).join(" ")}`,
    { cwd: repoRoot, encoding: "utf8", maxBuffer: 200 * 1024 * 1024 },
  )
} catch (err) {
  console.error("build-page-changelogs: git log failed:", err.message)
  process.exit(1)
}

// Parse the log into a map: filepath -> array of {sha, date, subject}
const fileHistory = new Map()
let currentCommit = null
for (const line of logRaw.split("\n")) {
  if (line.startsWith("COMMIT|")) {
    const parts = line.split("|")
    if (parts.length < 4) continue
    currentCommit = { sha: parts[1], date: parts[2].slice(0, 10), subject: parts.slice(3).join("|") }
  } else if (line.trim() && currentCommit) {
    if (!fileHistory.has(line)) fileHistory.set(line, [])
    const arr = fileHistory.get(line)
    // Skip duplicates (a file can appear once per commit; --name-only enforces this,
    // but defensive check in case --follow or rename detection surfaces both names)
    if (arr.length === 0 || arr[arr.length - 1].sha !== currentCommit.sha) {
      arr.push(currentCommit)
    }
  }
}

let updated = 0
let unchanged = 0
let noHistory = 0
let autoGenerated = 0

for (const targetDir of TARGETS) {
  const absDir = path.join(repoRoot, targetDir)
  if (!fs.existsSync(absDir)) continue
  for (const file of fs.readdirSync(absDir)) {
    if (!file.endsWith(".md")) continue
    if (file === "index.md") continue // folder index, not a citable atomic page
    if (file.startsWith("_")) continue
    const relPath = `${targetDir}/${file}`
    const absPath = path.join(repoRoot, relPath)
    const raw = fs.readFileSync(absPath, "utf8")
    const fmMatch = raw.match(/^---\n([\s\S]*?)\n---\n/)
    if (!fmMatch) { noHistory += 1; continue }

    const isAutoGen = /^auto_generated:\s*true\b/m.test(fmMatch[1])

    let block
    if (isAutoGen) {
      // Auto-generated pages: show the generator + last regeneration date.
      block = renderAutoGenBlock()
      autoGenerated += 1
    } else {
      const history = fileHistory.get(relPath) || []
      if (history.length === 0) {
        // No git history yet (file uncommitted). Render a minimal block.
        block = renderEmptyBlock()
      } else {
        block = renderHistoryBlock(history.slice(0, MAX_ENTRIES))
      }
    }

    const existingPattern = new RegExp(`\\n*${escapeRegExp(beginMarker)}[\\s\\S]*?${escapeRegExp(endMarker)}\\n*$`)
    let next
    if (existingPattern.test(raw)) {
      next = raw.replace(existingPattern, `\n\n${block}\n`)
    } else {
      next = `${raw.replace(/\n+$/, "")}\n\n${block}\n`
    }

    if (next === raw) {
      unchanged += 1
      continue
    }
    if (!dryRun) fs.writeFileSync(absPath, next, "utf8")
    updated += 1
    if (verbose) console.log(`  updated ${relPath}`)
  }
}

console.log(`build-page-changelogs: ${dryRun ? "DRY-RUN" : "EXECUTED"}`)
console.log(`  updated:        ${updated}`)
console.log(`  unchanged:      ${unchanged}`)
console.log(`  auto-generated: ${autoGenerated}`)
console.log(`  no frontmatter: ${noHistory}`)

function renderHistoryBlock(entries) {
  const rows = entries
    .map((e) => `| [${e.sha}](${GITHUB_BASE}/${e.sha}) | ${e.date} | ${escapePipes(e.subject)} |`)
    .join("\n")
  return `${beginMarker}
## Page history

The five most recent substantive edits to this page. The full version history lives in [git](https://github.com/paleofoundation/heavymetalindex); when DOI minting comes online (see [[../docs/schemas/index.md|schema docs]]), each entry below will also link to a version-pinned DataCite DOI.

| Commit | Date | Description |
| --- | --- | --- |
${rows}
${endMarker}`
}

function renderAutoGenBlock() {
  return `${beginMarker}
## Page history

This page is auto-regenerated from upstream data on every build. Edits by hand are overwritten on the next prebuild. See the generator named in the page intro for the data source and update cadence; the full commit history lives in [git](https://github.com/paleofoundation/heavymetalindex).
${endMarker}`
}

function renderEmptyBlock() {
  return `${beginMarker}
## Page history

This page has no committed history yet. Future edits will be recorded here once the change lands in git.
${endMarker}`
}

function escapePipes(value) {
  return String(value).replace(/\|/g, "\\|")
}

function escapeRegExp(value) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")
}
